class Solution {
public:
    int matrixMedian(vector<vector<int>>& g){
        long long lo=INT_MAX, hi=INT_MIN;
        for(auto&r:g){lo=min(lo,(long long)r.front());hi=max(hi,(long long)r.back());}
        long long need=(long long)g.size()*g[0].size()/2+1;
        while(lo<hi){
            long long mid=(lo+hi)/2, cnt=0;
            for(auto&r:g) cnt+=upper_bound(r.begin(),r.end(),mid)-r.begin();
            if(cnt>=need) hi=mid; else lo=mid+1;
        }
        return lo;
    }
};

