class Solution {
    public int matrixMedian(int[][] g){
        long lo=Integer.MAX_VALUE, hi=Integer.MIN_VALUE;
        for(int[] r:g){lo=Math.min(lo,r[0]);hi=Math.max(hi,r[r.length-1]);}
        long need=(long)g.length*g[0].length/2+1;
        while(lo<hi){
            long mid=(lo+hi)/2, cnt=0;
            for(int[] r:g) cnt+=upperBound(r,mid);
            if(cnt>=need) hi=mid; else lo=mid+1;
        }
        return (int)lo;
    }
    long upperBound(int[] r, long x){
        int l=0,h=r.length;
        while(l<h){int m=(l+h)/2; if(r[m]<=x)l=m+1;else h=m;}
        return l;
    }
}

