var matrixMedian = function(g) {
    let lo=Infinity, hi=-Infinity;
    for(const r of g){lo=Math.min(lo,r[0]);hi=Math.max(hi,r[r.length-1]);}
    const need = Math.floor(g.length*g[0].length/2)+1;
    const cntLE = x => g.reduce((s,r)=>{let l=0,h=r.length;while(l<h){const m=(l+h)>>1;if(r[m]<=x)l=m+1;else h=m;}return s+l;},0);
    while(lo<hi){
        const mid=Math.floor((lo+hi)/2);
        if(cntLE(mid)>=need) hi=mid; else lo=mid+1;
    }
    return lo;
};
